#### a) Pseudocode (C++ version)

```cpp
array<int, 2> findMinMax(int A[], int l, int r) {
    int max, min;
    if (l == r) {
        max = A[l];
        min = A[l];
    } else if (l + 1 == r) {
        if (A[l] < A[r]) {
            max = A[r];
            min = A[l];
        } else {
            max = A[l];
            min = A[r];
        }
    } else {
        int mid = l + (r - l) / 2;
        array<int, 2> left = findMinMax(A, l, mid);
        array<int, 2> right = findMinMax(A, mid + 1, r);
        if (left[0] > right[0]) max = left[0];
        else max = right[0];
        if (left[1] < right[1]) min = left[1];
        else min = right[1];
    }
    return { max, min };   // {max, min}
}
```

#### Pseudocode (handwritten form)

```text
Func MinMax(A[l..r], min, max)
    if (r == l)
