int KnapsackBU(int wt[], int price[], int n, int cap) {
    vector<vector<int>> Strg(n + 1, vector<int>(cap + 1, 0));
    for (int row = n - 1; row >= 0; row--) {
        for (int col = 1; col <= cap; col++) {
            int exclude = Strg[row + 1][col];
            int include = 0;
            if (col >= wt[row])
                include = Strg[row + 1][col - wt[row]] + price[row];
            Strg[row][col] = max(exclude, include);
        }
    }
    return Strg[0][cap];
}
```

