int LCSTD(string S1, string S2, int vidx1, int vidx2, int **strg) {
    if (vidx1 == S1.length() || vidx2 == S2.length())
        return 0;
    if (strg[vidx1][vidx2] != -1)
        return strg[vidx1][vidx2];
    int ans;
