        ans = LCSTD(S1, S2, vidx1 + 1, vidx2 + 1, strg) + 1;
    else {
        int o1 = LCSTD(S1, S2, vidx1, vidx2 + 1, strg);
        int o2 = LCSTD(S1, S2, vidx1 + 1, vidx2, strg);
        ans = max(o1, o2);
    }
    strg[vidx1][vidx2] = ans;
    return ans;
}
