**Backtracking** is a general problem-solving technique that explores all possible solutions by incrementally building a candidate solution and discarding it as soon as it is determined that it cannot lead to a solution, then proceeding along a different path. This is done by going back to the last choice point and trying a different option. It continues until a solution is found or all possible choices have been explored.

**N-Queens: queen's perspective**

```cpp
bool isItSafe(bool board[][n], int row, int col) {
    int r = row - 1, c = col;          // vertically up
    while (r >= 0) {
        if (board[r][c] == 1) return false;
        r--;
    }
    r = row - 1; c = col - 1;          // diagonally left
    while (r >= 0 && c >= 0) {
        if (board[r][c] == 1) return false;
        r--; c--;
    }
    r = row - 1; c = col + 1;          // diagonally right
    while (r >= 0 && c < n) {
        if (board[r][c] == 1) return false;
        r--; c++;
    }
    return true;
}

void nQueen(bool board[][n], int row, string ans) {
    if (row == n) {
        cout << ans << endl;
        return;
    }
    for (int col = 0; col < n; col++) {
        if (isItSafe(board, row, col)) {
            board[row][col] = true;
            nQueen(board, row + 1, ans + "{" + to_string(row) + "-" + to_string(col) + "}");
            board[row][col] = false;
        }
    }
}
```

