**Subset sum problem**

It is a backtracking problem of finding whether a subset of a given set of integers has a sum equal to a given target number.

```cpp
void SubsetSum(vector<int>& S, vector<int>& path, int target, int start, int sum) {
    if (sum == target) {
        // print the path in vector path
        return;
    }
    if (sum > target || start == S.size())
        return;                                         // no path found
    path.push_back(S[start]);                           // include
    SubsetSum(S, path, target, start + 1, sum + S[start]);
    path.pop_back();                                    // exclude
    SubsetSum(S, path, target, start + 1, sum);
}
```

A **Hamiltonian cycle** is a cycle (or path) in a graph that passes through every vertex exactly once, forming a closed path that returns to its starting point.

```cpp
bool hamiltonian(int src, int curr, int path[], int idx) {
    if (idx == V) {
        if (dp[src].count(curr) != 0) {          // last vertex connects back to src
            for (int i = 0; i < V; i++)
                cout << path[i] << " ";
            cout << endl;
            return true;
        }
        return false;
    }
    bool ans = false;
    map<int, int>::iterator itr;
    for (itr = dp[curr].begin(); itr != dp[curr].end(); itr++) {
        int nbr = itr->first;
        if (isItSafe(path, nbr)) {
            path[idx] = nbr;
            ans = hamiltonian(src, nbr, path, idx + 1) || ans;
            path[idx] = -1;                      // backtrack
        }
    }
    return ans;
}
```
